fn main() {
    // Ownership rules:
    // 1. Each value has one owner
    // 2. When owner goes out of scope, value is dropped
    // 3. References borrow without taking ownership

    let s1 = String::from("hello");
    let s2 = s1;  // Ownership moves to s2, s1 is no longer valid
    // println!("{}", s1);  // ERROR: s1 was moved

    // Borrowing with references
    let s3 = String::from("world");
    let len = calculate_length(&s3);  // &s3 borrows without ownership
    println!("'{}' has length {}", s3, len);  // s3 still usable

    // Mutable reference (only one allowed at a time)
    let mut s4 = String::from("hello");
    change(&mut s4);
}

fn calculate_length(s: &String) -> usize {
    s.len()  // s is a reference, but we can still access fields
}  // s goes out of scope, but since it's a reference, nothing happens

fn change(s: &mut String) {
    s.push_str(", world");
}

